import java.sql.*;
/** Stores all Settings-panel components in the existing rule table. */
public class PayrollSettingsDAO {
 private static PayrollSettings cached=new PayrollSettings();
 public PayrollSettings load(){PayrollSettings out=new PayrollSettings();try(Connection c=DBConnection.getConnection();PreparedStatement p=c==null?null:c.prepareStatement("SELECT rule_name,rule_value FROM settings_attendance_leave_rules WHERE rule_name LIKE 'PAYROLL:%'")){if(p==null)return cached;ResultSet r=p.executeQuery();boolean any=false;while(r.next()){PayrollSettings.Component x=out.getComponents().get(r.getString(1).substring(8));if(x==null)continue;String[] v=r.getString(2).split("\\|",-1);if(v.length==3){x.enabled="1".equals(v[0]);x.value=Double.parseDouble(v[1]);x.percentage="1".equals(v[2]);any=true;}}if(any)cached=out;}catch(Exception ignored){}return cached;}
 public void save(PayrollSettings settings)throws SQLException{Connection c=DBConnection.getConnection();if(c==null)return;c.setAutoCommit(false);try(PreparedStatement p=c.prepareStatement("INSERT INTO settings_attendance_leave_rules(rule_name,rule_value) VALUES(?,?) ON CONFLICT(rule_name) DO UPDATE SET rule_value=excluded.rule_value")){for(java.util.Map.Entry<String,PayrollSettings.Component> e:settings.getComponents().entrySet()){PayrollSettings.Component x=e.getValue();p.setString(1,"PAYROLL:"+e.getKey());p.setString(2,(x.enabled?1:0)+"|"+x.value+"|"+(x.percentage?1:0));p.addBatch();}p.executeBatch();c.commit();cached=settings;}catch(SQLException e){c.rollback();throw e;}finally{c.setAutoCommit(true);}}
}
